using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.DTOs; using InventorySystem.Application.Interfaces;
namespace InventorySystem.Application.Features.Products.Queries;
public record GetProductsQuery(string? Search=null,int Page=1,int PageSize=20) : IRequest<PagedResult<ProductDto>>;
public class GetProductsQueryHandler(IAppDbContext db) : IRequestHandler<GetProductsQuery,PagedResult<ProductDto>> { public async Task<PagedResult<ProductDto>> Handle(GetProductsQuery r,CancellationToken ct){ var q=db.Products.AsNoTracking().Where(x=>!x.IsDeleted); if(!string.IsNullOrWhiteSpace(r.Search)) q=q.Where(x=>x.Name.Contains(r.Search)||x.SKU.Contains(r.Search)); var page=Math.Max(1,r.Page); var size=Math.Clamp(r.PageSize,1,100); var total=await q.CountAsync(ct); var items=await q.OrderBy(x=>x.Name).Skip((page-1)*size).Take(size).Select(x=>new ProductDto(x.Id,x.Name,x.SKU,x.Barcode,x.PurchasePrice,x.SellingPrice,x.MinimumStock,x.Category.Name,x.StockItems.Where(s=>!s.IsDeleted).Sum(s=>s.Quantity),x.CategoryId,x.Description,x.SupplierId,x.Supplier == null ? null : x.Supplier.Name)).ToListAsync(ct); return new PagedResult<ProductDto>(items,total,page,size); } }
